"use client";

import RestartAltOutlinedIcon from "@mui/icons-material/RestartAltOutlined";
import SearchOutlinedIcon from "@mui/icons-material/SearchOutlined";
import { Box, Button, Card, CardContent, InputAdornment, TextField } from "@mui/material";

import { standardFieldSx } from "@/components/common/FormControls";

export type SearchPanelProps = {
  keyword: string;
  onKeywordChange: (keyword: string) => void;
  onSearch: () => void;
  onReset: () => void;
  children?: React.ReactNode;
};

export function SearchPanel({ keyword, onKeywordChange, onSearch, onReset, children }: SearchPanelProps) {
  return (
    <Card sx={{ mb: 2 }}>
      <CardContent>
        <Box
          component="form"
          onSubmit={(event) => {
            event.preventDefault();
            onSearch();
          }}
          sx={{ display: "flex", flexDirection: { xs: "column", md: "row" }, gap: 2, alignItems: "center" }}
        >
          <TextField
            fullWidth
            label="검색어"
            onChange={(event) => onKeywordChange(event.target.value)}
            placeholder="이름, 이메일, 부서명 검색"
            size="small"
            sx={standardFieldSx}
            value={keyword}
            slotProps={{
              input: {
                startAdornment: (
                  <InputAdornment position="start">
                    <SearchOutlinedIcon fontSize="small" />
                  </InputAdornment>
                ),
              },
            }}
          />
          {children}
          <Button color="primary" onClick={onSearch} sx={{ minWidth: 120 }} variant="contained">
            조회
          </Button>
          <Button
            color="inherit"
            onClick={onReset}
            startIcon={<RestartAltOutlinedIcon />}
            sx={{ minWidth: 120 }}
            variant="outlined"
          >
            초기화
          </Button>
        </Box>
      </CardContent>
    </Card>
  );
}
